    /* ── Principles ── */
    "Separate deploy from release": K("Principle", "Deploying code and exposing it to users are different decisions with different risks; keep them apart.", ["Deploy dark", "Release by flag, ring by ring"], dodont(["Deploy with exposure off", "Expose deliberately, in steps"], ["Make every deployment a big-bang launch"]), { source: "ITIL 4; progressive delivery" }),
    "A named person, a date, a decision": K("Principle", "A release exists when an accountable person records go, no-go or go with conditions on a date — not when code reaches production.", ["Name the decider before the release", "Record the decision with the date"], dodont(["Agree the decider in advance", "Record every outcome, including no-go"], ["Let the deployment 'just happen'"]), { source: "Delivery manual — The Release Gate" }),
    "Evidence over assertion": K("Principle", "A sentence is not evidence; every release criterion links to the artifact that proves it, for this build.", ["Link an artifact to every criterion", "Check it names the release build"], dodont(["Link the test run for the release build"], ["Accept 'QA said it's fine'"])),
    "Limit the blast radius": K("Principle", "Expose change so that a failure hurts as few users as possible, for as short a time as possible.", ["Start small", "Make it reversible", "Watch before widening"], dodont(["Pilot with a few trained users", "Keep a kill switch"], ["Turn it on for everyone at once"])),
    "Roll back first, diagnose later": K("Principle", "When a pre-agreed trigger fires, restore service first; investigate once users are safe.", ["Agree triggers in advance", "Give on-call the right to roll back without asking"], dodont(["Pull the flag on a breached threshold"], ["Debug in production while users suffer"]), { source: "SRE practice" }),
    "Exclude explicitly, with reasons": K("Principle", "What is not in the release is written down with the reason, and the people who asked for it are told before deployment.", ["List exclusions and reasons", "Tell requesters"], dodont(["Record STY-122 and why it waits"], ["Let work silently drop out"]), { source: "Delivery manual — The excluded Story" }),
    "Ready before exposed": K("Principle", "Support, communications, documentation and training are ready for a group of users before that group is exposed.", ["Check readiness per ring"], dodont(["Train a site before its ring"], ["Announce first, train later"])),
    "Small, frequent releases": K("Principle", "Smaller releases are easier to verify, decide on, roll back and learn from.", ["Release verified increments as soon as they are ready"], dodont(["Ship a few stories at a time"], ["Batch a quarter's work into one release"]), { source: "DORA research" }),

